"""Node.js subprocess runner.

Lighter-weight alternative to ``DockerSandboxRunner`` for development and CI
where launching Docker per test is impractical. The trade-off is that the
candidate code runs with the host's Node permissions — this is acceptable
for the M2 deobfuscation pipeline because:

* candidate code is generated by an LLM responding to a prompt that explicitly
  asks for a deobfuscated function — we are not executing arbitrary samples
* the host invokes the runner with a strict timeout, no network credentials,
  and an artificial CWD
* every test case is wrapped in a child VM context (``vm.Script`` + sandbox
  globals) so the candidate cannot reach into the host process

Production deployments should still prefer :class:`DockerSandboxRunner`.
"""

from __future__ import annotations

import asyncio
import json
import shutil
import time
from dataclasses import dataclass
from pathlib import Path
from tempfile import TemporaryDirectory


@dataclass(slots=True)
class TestCaseResult:
    name: str
    passed: bool
    actual: object | None = None
    expected: object | None = None
    error: str | None = None
    duration_ms: int | None = None


@dataclass(slots=True)
class NodeRunResult:
    passed: int
    total: int
    pass_ratio: float
    cases: list[TestCaseResult]
    runner_stderr: str
    runner_exit_code: int
    timed_out: bool

    def to_dict(self) -> dict:
        return {
            "passed": self.passed,
            "total": self.total,
            "pass_ratio": self.pass_ratio,
            "timed_out": self.timed_out,
            "cases": [
                {
                    "name": c.name,
                    "passed": c.passed,
                    "actual": c.actual,
                    "expected": c.expected,
                    "error": c.error,
                    "duration_ms": c.duration_ms,
                }
                for c in self.cases
            ],
        }


_RUNNER_SCRIPT_PATH = Path(__file__).parent / "_runner.js"


class NodeSubprocessRunner:
    """Executes a candidate JS module against a list of semantic test cases."""

    def __init__(
        self,
        *,
        node_binary: str = "node",
        timeout_seconds: int = 15,
    ) -> None:
        resolved = shutil.which(node_binary)
        if resolved is None:
            msg = f"Node binary not found on PATH: {node_binary}"
            raise FileNotFoundError(msg)
        self._node = resolved
        self._timeout_seconds = timeout_seconds

    async def run(
        self,
        *,
        candidate_code: str,
        export_name: str,
        test_cases: list[dict],
    ) -> NodeRunResult:
        """Execute ``candidate_code`` and dispatch each test case.

        ``export_name`` is the function exported from the candidate that
        gets called with positional ``args`` from each test case.
        """
        if not test_cases:
            return NodeRunResult(
                passed=0,
                total=0,
                pass_ratio=0.0,
                cases=[],
                runner_stderr="no test cases provided",
                runner_exit_code=0,
                timed_out=False,
            )

        if not _RUNNER_SCRIPT_PATH.exists():
            msg = f"runner script missing at {_RUNNER_SCRIPT_PATH}"
            raise FileNotFoundError(msg)

        with TemporaryDirectory(prefix="js-re-bench-runner-") as tmp:
            tmp_dir = Path(tmp)
            (tmp_dir / "candidate.js").write_text(candidate_code, encoding="utf-8")
            (tmp_dir / "cases.json").write_text(
                json.dumps({"export": export_name, "cases": test_cases}),
                encoding="utf-8",
            )

            argv = [
                self._node,
                "--no-warnings",
                str(_RUNNER_SCRIPT_PATH),
                str(tmp_dir / "candidate.js"),
                str(tmp_dir / "cases.json"),
            ]
            t0 = time.monotonic()
            proc = await asyncio.create_subprocess_exec(
                *argv,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                cwd=tmp_dir,
            )
            timed_out = False
            try:
                stdout, stderr = await asyncio.wait_for(
                    proc.communicate(),
                    timeout=self._timeout_seconds,
                )
            except TimeoutError:
                proc.kill()
                stdout, stderr = await proc.communicate()
                timed_out = True
            duration_ms = int((time.monotonic() - t0) * 1000)

            if timed_out:
                return NodeRunResult(
                    passed=0,
                    total=len(test_cases),
                    pass_ratio=0.0,
                    cases=[
                        TestCaseResult(
                            name=str(c.get("name", f"case_{i}")),
                            passed=False,
                            expected=c.get("expected"),
                            error="runner timed out",
                            duration_ms=duration_ms,
                        )
                        for i, c in enumerate(test_cases)
                    ],
                    runner_stderr=(stderr or b"").decode("utf-8", "replace")[-2000:],
                    runner_exit_code=-1,
                    timed_out=True,
                )

            try:
                payload = json.loads(stdout.decode("utf-8") or "{}")
            except json.JSONDecodeError:
                return NodeRunResult(
                    passed=0,
                    total=len(test_cases),
                    pass_ratio=0.0,
                    cases=[],
                    runner_stderr=stderr.decode("utf-8", "replace")[-2000:],
                    runner_exit_code=proc.returncode or -1,
                    timed_out=False,
                )

            cases = [
                TestCaseResult(
                    name=str(c.get("name", "")),
                    passed=bool(c.get("passed")),
                    actual=c.get("actual"),
                    expected=c.get("expected"),
                    error=c.get("error"),
                    duration_ms=c.get("duration_ms"),
                )
                for c in payload.get("cases", [])
            ]
            passed = sum(1 for c in cases if c.passed)
            total = len(cases)
            return NodeRunResult(
                passed=passed,
                total=total,
                pass_ratio=passed / total if total else 0.0,
                cases=cases,
                runner_stderr=stderr.decode("utf-8", "replace")[-2000:],
                runner_exit_code=proc.returncode or 0,
                timed_out=False,
            )
